 if(k==='build')h='<h2>Letters ready</h2><p class="muted">'+nSel()+' items across 3 bureaus, written from the facts on the report.</p>'+letterDoc('Equifax')+'<div class="note info" style="margin-top:12px">Rule check: only facts from the report · wording unique to this client · consumer-law based'+(ITEMS.some(function(i){return S.sel[i.id]==='dispute'&&METH[i.id]==='custom';})?' · '+ITEMS.filter(function(i){return S.sel[i.id]==='dispute'&&METH[i.id]==='custom';}).length+' item(s) written from your own reasons (demo shows your words as typed; the live app rewrites them uniquely)':'')+'</div>';
 if(k.indexOf('letter:')===0)h='<h2>'+k.split(':')[1]+' letter</h2>'+letterDoc(k.split(':')[1]);
 if(k.indexOf('packet:')===0){var pb=k.split(':')[1];var diy=S.mode==='diy';var A_=S.att;var n=1+(A_.id?1:0)+(A_.addr?1:0)+(A_.poa?1:0)+(A_.ssn?1:0);
 function att(key,label,note,req){return '<label class="pg" style="cursor:pointer"><input type="checkbox" data-att="'+key+'" '+(A_[key]?'checked':'')+' '+((diy&&req)?'disabled':'')+'><i></i><div class="grow"><b>'+label+'</b><div class="sub">'+note+'</div></div><span class="chip '+(A_[key]?'good':'')+'">'+(A_[key]?'Attached':'Left off')+'</span></label>';}
 h='<h2>PDF packet: '+pb+'</h2><p class="muted">'+n+' pages. The letter comes first, then each attachment on its own page, like your printed set.</p><div class="pages"><div class="pg"><i></i><div class="grow"><b>Dispute letter</b><div class="sub">'+(S.split?'One item per letter':nSel()+' items on one letter')+'</div></div><span class="chip '+(S.signed?'good':'warn')+'">'+(S.signed?'Signed':'Needs signature')+'</span></div>'+att('id','Photo ID','Full page','1')+att('addr','Proof of address','Full page','1')+att('poa','Power of attorney','Only if the client chose it','')+att('ssn','SSN card or document','Optional','')+'</div>'+(diy?'<div class="note info">Photo ID and proof of address are attached to every letter.</div>':'<div class="note info">As an agent you can leave any attachment off for this packet.</div>')+'<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:12px"><button class="btn pri">Download PDF</button><button class="btn">Print</button><button class="btn" data-drive="save:packet">Save to my Drive</button></div>';S.lastModal=k;}
 if(k.indexOf('email:')===0){var em=EMAILS[+k.split(':')[1]];h='<h2>'+esc(em[0])+'</h2><div class="sub">Subject: '+esc(em[2])+'</div><div class="letter" style="margin-top:12px">'+esc(em[3])+'</div>';}
